var game=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassGameFlow>();var player=game.Player.GetComponent<Cheon.Prototype.MountainPass.PassPlayerMovement>();var data=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("Assets/Temp/MountainPassRefinement~/Test_StepGeometry.json"));var checks=new System.Collections.Generic.List<object>();var body=player.GetComponent<CharacterController>();
System.Collections.IEnumerator Routine(){game.BeginJourney();game.Boss.enabled=false;player.InputEnabled=false;for(int index=0;index<2;index++){var d=data[index==0?30:65];var origin=new Vector3((float)d["center"][0],(float)d["center"][1]+.06f,(float)d["center"][2]);var right=new Vector3((float)d["right"][0],0,(float)d["right"][2]);for(int side=0;side<2;side++){player.Teleport(origin,Quaternion.identity);float before=player.transform.position.y;for(int frame=0;frame<24;frame++){body.Move(right*(side==0?-1:1)*.3f-Vector3.up*.03f);yield return null;}var offset=Vector3.Dot(player.transform.position-origin,right);float edge=side==0?-(float)d["left"]:(float)d["rightWidth"];checks.Add(new{stair=index,side,offset,edge,y=player.transform.position.y,blocked=Mathf.Abs(offset)<edge+.2f&&player.transform.position.y>before-.6f});}}
